concept.cypher:
MATCH (c:Class)
// 1. Gérer les classes internes (on ne garde que la classe maîtresse avant le '$')
WITH c, split(c.fqn, '$')[0] AS baseFqn

// 2. Transformer le FQN en format de chemin de fichier (points -> slashs)
WITH c, replace(baseFqn, '.', '/') + '.java' AS expectedPathPattern

// 3. Matcher avec le fichier physique
MATCH (f:File)
WHERE f.fileName ENDS WITH expectedPathPattern
OR replace(f.fileName, '\\', '/') ENDS WITH expectedPathPattern // Sécurisation Windows

// 4. Créer la relation explicite dans le graphe
MERGE (c)-[:HAS_SOURCE_FILE]->(f)
RETURN count(c) AS LinkedClasses

// 1. Trouver le point d'entrée Spring Boot MATCH (main:Class)-[:ANNOTATED_BY]->()-[:OF_TYPE]->(t:Type) WHERE t.fqn = 'org.springframework.boot.autoconfigure.SpringBootApplication'
// 2. Trouver les classes candidates de l'application MATCH (c:Class) WHERE NOT c.fqn STARTS WITH 'java.' AND NOT c.fqn STARTS WITH 'org.spring' AND NOT c:Controller AND NOT c.name ENDS WITH 'Test' AND NOT c.name ENDS WITH 'Application' // Fusion des conditions : Aucun chemin de dépendance depuis la Main AND NOT (main)-[:DEPENDS_ON|INVOKES*]->(c)
// 3. Marquage SET c:DeadCodeCandidate RETURN count(c) AS DeadCodeCandidates
